var url = "http://widget.weibo.com/distribution/comments.php?width=0"
+ "&url=" + cmurl
+ "&border=1&brandline=y&fontsize=14&appkey=1209711650&language=zh_cn&dpc=1";
//alert(url);
document.write('<iframe id="WBCommentFrame" src="' + url + '" scrolling="no" frameborder="0" style="width:100%"></iframe>');
})();
</script>
